// Open connection, identify as "DaemonName", log PID, use LOG_USER facility
openlog("DaemonName", LOG_PID | LOG_NDELAY, LOG_USER);

int resource_id = 123;
char* user = "admin";

// Log high-priority error (writes to /var/log/syslog, auth.log, etc., based on configuration)
syslog(LOG_AUTH | LOG_CRIT, "Unauthorized access attempt by %s.", user);

// Log informational message
syslog(LOG_INFO, "Resource %d successfully allocated.", resource_id);

// Using variadic arguments style (printf format)
int bytes_written = 1024;
syslog(LOG_DEBUG, "Wrote %d bytes to temporary buffer.", bytes_written);

// Close connection
closelog();
